"""Shared data conversions, dates, and small configuration readers."""
import os, re, json, time, datetime, calendar, unicodedata

class Failure(Exception):
    def __init__(self, text, prefix=True):
        self.text=text; self.prefix=prefix

class Moment:
    def __init__(self, ns=None, offset=0):
        self.ns=time.time_ns() if ns is None else int(ns)
        self.offset=offset
    @property
    def dt(self):
        return datetime.datetime.fromtimestamp(self.ns//1000000000, datetime.timezone(datetime.timedelta(seconds=self.offset)))
    def iso(self):
        d=self.dt; sub=self.ns%1000000000
        tail=('Z' if not self.offset else d.strftime('%z')[:3]+':'+d.strftime('%z')[3:])
        return d.strftime('%Y-%m-%dT%H:%M:%S')+('.'+str(sub).zfill(9).rstrip('0') if sub else '')+tail
    def __str__(self):
        d=self.dt; sub=self.ns%1000000000
        return d.strftime('%Y-%m-%d %H:%M:%S')+('.'+str(sub).zfill(9).rstrip('0') if sub else '')+d.strftime(' %z ')+('UTC' if self.offset==0 else '')

def json_ready(x):
    if isinstance(x,Moment):return x.iso()
    if isinstance(x,dict):return {k:json_ready(v) for k,v in x.items() if not str(k).startswith('_')}
    if isinstance(x,(tuple,list)):return [json_ready(v) for v in x]
    return x

def jdump(x):
    return json.dumps(json_ready(x),ensure_ascii=False,separators=(',',':')).replace('&','\\u0026').replace('<','\\u003c').replace('>','\\u003e').replace('\u2028','\\u2028').replace('\u2029','\\u2029')

def gstr(x):
    if x is None:return ''
    if isinstance(x,bool):return 'true' if x else 'false'
    if isinstance(x,(list,tuple)):return ''.join(gstr(v) for v in x)
    if isinstance(x,dict):return 'map['+' '.join(str(k)+':'+gstr(x[k]) for k in sorted(x))+']'
    return str(x)

def scalar(s, yaml=False):
    s=s.strip()
    if not s:return None if yaml else ''
    if s.startswith('"') and s.endswith('"'):
        try:return json.loads(s)
        except:return s[1:-1]
    if s.startswith("'") and s.endswith("'"):return s[1:-1].replace("''", "'") if yaml else s[1:-1]
    low=s.lower()
    if low in ['true','false'] or (yaml and low in ['yes','no','on','off']):return low in ['true','yes','on']
    if yaml and low in ['null','~']:return None
    if re.fullmatch(r'[+-]?\d[\d_]*',s):
        try:return int(s.replace('_',''))
        except:pass
    if re.fullmatch(r'[+-]?\d[\d_]*\.\d+(?:[eE][+-]?\d+)?',s):
        try:return float(s.replace('_',''))
        except:pass
    if s.startswith('['):
        if not s.endswith(']'):raise ValueError('did not find expected node content')
        return [scalar(v,yaml) for v in split_quoted(s[1:-1],',') if v.strip()]
    if s.startswith('{'):
        if not s.endswith('}'):raise ValueError("did not find expected ',' or '}'")
        d={}
        for part in split_quoted(s[1:-1],','):
            sep=':' if yaml else '='
            kv=split_quoted(part,sep,once=True)
            if len(kv)==2:d[str(scalar(kv[0],yaml))]=scalar(kv[1],yaml)
        return d
    return s

def split_quoted(s, sep=',', once=False):
    a=[]; start=0; quote=''; depth=0; esc=False
    for i,ch in enumerate(s):
        if esc:esc=False;continue
        if quote:
            if ch=='\\' and quote=='"':esc=True
            elif ch==quote:quote=''
        elif ch in "\"'":quote=ch
        elif ch in '[{(':depth+=1
        elif ch in ']})':depth-=1
        elif depth==0 and ch==sep:
            a.append(s[start:i]);start=i+1
            if once:a.append(s[start:]);return a
    a.append(s[start:]);return a

def strip_comment(s):
    quote='';esc=False
    for i,ch in enumerate(s):
        if esc:esc=False;continue
        if quote:
            if ch=='\\' and quote=='"':esc=True
            elif ch==quote:quote=''
        elif ch in "\"'":quote=ch
        elif ch=='#' and (i==0 or s[i-1].isspace()):return s[:i].rstrip()
    return s

def simple_toml(text):
    out={};cur=out;ls=text.splitlines();i=0
    while i<len(ls):
        line=strip_comment(ls[i]).strip();i+=1
        if not line:continue
        if line.startswith('[') and line.endswith(']'):
            path=split_quoted(line[1:-1],'.');cur=out
            for key in path:cur=cur.setdefault(str(scalar(key)),{})
            continue
        kv=split_quoted(line,'=',once=True)
        if len(kv)!=2:raise ValueError('invalid key-value pair')
        key=str(scalar(kv[0]));val=kv[1].strip()
        if val.startswith(('"""',"'''")):
            q=val[:3];val=val[3:]
            if not val:val=''
            while q not in val and i<len(ls):val+= ('\n' if val else '')+ls[i];i+=1
            cur[key]=val.split(q)[0];continue
        if val.startswith('['):
            while not val.endswith(']') and i<len(ls):val+=' '+strip_comment(ls[i]).strip();i+=1
        cur[key]=scalar(val)
    return out

def read_toml(text):
    try:
        import tomllib
        return tomllib.loads(text)
    except ImportError:pass
    try:
        import tomli
        return tomli.loads(text)
    except ImportError:return simple_toml(text)

def yaml_load(text):
    lines=text.splitlines()
    def parse(pos,indent):
        result=None
        while pos<len(lines):
            raw=lines[pos]
            if not raw.strip() or raw.lstrip().startswith('#'):pos+=1;continue
            level=len(raw)-len(raw.lstrip())
            if level<indent:break
            s=strip_comment(raw.strip())
            if s.startswith('- ') or s=='-':
                if result is None:result=[]
                if not isinstance(result,list):break
                val=s[1:].strip()
                if not val:
                    val,pos=parse(pos+1,level+2)
                else:val=scalar(val,True);pos+=1
                result.append(val)
            else:
                if result is None:result={}
                if not isinstance(result,dict):break
                kv=split_quoted(s,':',once=True)
                if len(kv)!=2:raise ValueError("could not find expected ':'")
                key=str(scalar(kv[0],True));val=kv[1].strip();pos+=1
                if val in ['|','>','|-','>-','|+','>+']:
                    parts=[]
                    while pos<len(lines) and (not lines[pos].strip() or len(lines[pos])-len(lines[pos].lstrip())>level):
                        parts.append(lines[pos][level+2:] if lines[pos].strip() else '');pos+=1
                    v=(' ' if val.startswith('>') else '\n').join(parts)
                    if not val.endswith('-'):v+='\n'
                    result[key]=v
                elif not val:
                    peek=pos
                    while peek<len(lines) and not lines[peek].strip():peek+=1
                    if peek<len(lines) and len(lines[peek])-len(lines[peek].lstrip())>level:
                        v,pos=parse(pos,len(lines[peek])-len(lines[peek].lstrip()));result[key]=v
                    else:result[key]=None
                else:result[key]=scalar(val,True)
        return (result or {}),pos
    result,_=parse(0,0)
    return result if isinstance(result,dict) else {}

def merge(a,b):
    out=dict(a)
    for k,v in b.items():
        if isinstance(v,dict) and isinstance(out.get(k),dict):out[k]=merge(out[k],v)
        else:out[k]=v
    return out

def parse_date(s,now=None):
    if isinstance(s,Moment):return s
    now=now or Moment();d=now.dt;s=str(s).strip();low=s.lower()
    if not s or low=='now':return now
    # RFC3339, calendar dates, and the usual slash-based input forms.
    m=re.fullmatch(r'(\d{4})-(\d\d)-(\d\d)(?:[Tt](\d\d):(\d\d):(\d\d)(?:\.(\d+))?([Zz]|[+-]\d\d:\d\d))?',s)
    if m:
        try:
            y,mo,day=[int(x) for x in m.group(1,2,3)];hh,mi,ss=[int(x or 0) for x in m.group(4,5,6)]
            zone=m.group(8);offset=0
            if zone and zone not in 'Zz':offset=(1 if zone[0]=='+' else -1)*(int(zone[1:3])*3600+int(zone[4:])*60)
            dt=datetime.datetime(y,mo,day,hh,mi,ss,tzinfo=datetime.timezone(datetime.timedelta(seconds=offset)))
            ns=int(dt.timestamp())*1000000000+int((m.group(7) or '').ljust(9,'0')[:9] or 0)
            return Moment(ns,offset)
        except:pass
    for f in ['%Y/%m/%d','%m/%d/%Y','%m/%d/%y','%B %d, %Y','%b %d, %Y','%d %B %Y','%d %b %Y']:
        try:
            dt=datetime.datetime.strptime(s,f).replace(tzinfo=datetime.timezone.utc);return Moment(int(dt.timestamp())*1000000000)
        except:pass
    midnight=d.replace(hour=0,minute=0,second=0,microsecond=0)
    if low in ['today','yesterday','tomorrow']:
        dd={'today':0,'yesterday':-1,'tomorrow':1}[low];return Moment(int((midnight+datetime.timedelta(days=dd)).timestamp())*1000000000)
    nums={'a':1,'an':1,'one':1,'two':2,'three':3,'four':4,'five':5,'six':6,'seven':7,'eight':8,'nine':9,'ten':10}
    m=re.fullmatch(r'(?:(last|next|in) )?(\d+|a|an|one|two|three|four|five|six|seven|eight|nine|ten)?\s*(second|minute|hour|day|week|month|year)s?( ago)?',low)
    if m:
        n=m.group(2) or '1';n=int(n) if n.isdigit() else nums[n]
        if m.group(1)=='last' or m.group(4):n=-n
        unit=m.group(3)
        seconds={'second':1,'minute':60,'hour':3600,'day':86400,'week':604800,'month':2592000,'year':31536000}[unit]
        base=now.ns if unit in ['second','minute','hour'] else int(midnight.timestamp())*1000000000
        return Moment(base+n*seconds*1000000000)
    if low.startswith(('last ','next ','this ')):
        w=low.split()[-1]
        weekdays=[x.lower() for x in calendar.day_name]
        if w in weekdays:
            delta=weekdays.index(w)-d.weekday()
            if low.startswith('last') and delta>=0:delta-=7
            if low.startswith('next') and delta<=0:delta+=7
            return Moment(int((midnight+datetime.timedelta(days=delta)).timestamp())*1000000000)
    if re.match(r'\d{4}-',s) and len(s)>10:
        raise Failure('\nparse error near PegText (line 1 symbol 1 - line 1 symbol 5):\n"'+s[:4]+'"\n')
    return Moment(int(midnight.timestamp())*1000000000)

def date_fmt(value,fmt=None,language='en'):
    if value is None:return ''
    if not isinstance(value,Moment):
        try:value=parse_date(value)
        except:return ''
    fmt=fmt or '%Y-%m-%d'
    fmts={'short':'%m/%d/%Y','medium':'%b %d, %Y','long':'%B %d, %Y','full':'%A, %B %d, %Y','time':'%H:%M','timestamp':'%Y%m%d%H%M'}
    fmt=fmts.get(fmt,fmt)
