def new(cli,book,cwd):
    opts=cli.opts;patharg=cli.paths[0] if cli.paths else cwd
    targetdir=os.path.abspath(os.path.join(cwd,os.path.expanduser(patharg)))
    if not os.path.isdir(targetdir):raise Failure('new note: '+patharg+': directory not found')
    rel=os.path.relpath(targetdir,book.root)
    if rel=='..' or rel.startswith('../'):raise Failure('new note: '+targetdir+': path is outside the notebook at '+book.root)
    if rel=='.':rel=''
    conf=book.options(rel,opts.get('group'));no=conf['note'];now=parse_date(opts['date']) if 'date' in opts else Moment()
    title=opts.get('title') or no.get('default-title','Untitled')
    content=sys.stdin.read() if opts.get('interactive') else ''
    extra=merge(conf.get('extra',{}),opts.get('extra',{}));extra={k:extra[k] for k in sorted(extra)}
    env=dict(os.environ);env['ZK_NOTEBOOK_DIR']=book.root;env['ZK_SHELL']=os.environ.get('SHELL','')
    env={k:env[k] for k in sorted(env)}
    fixed=opts.get('id','');template=Templates(no.get('language','en'))
    for attempt in range(200):
        if fixed:ident=fixed
        else:
            charset=no.get('id-charset','alphanum');charset={'alphanum':string.ascii_lowercase+string.digits,'letters':string.ascii_lowercase,'numbers':string.digits,'hex':'abcdef0123456789'}.get(charset,charset)
            case=no.get('id-case','lower')
