            elif case=='mixed':charset+=''.join(c.upper() for c in charset if c.isalpha())
            elif case!='lower':raise Failure('new note: '+case+': invalid ID letter case')
            size=no.get('id-length',4)
            if size<0 or size>10000:raise Failure('new note: invalid ID length')
            ident=''.join(random.choice(charset) for _ in range(size))
        ctx={'ID':ident,'Title':title,'Content':content,'Dir':rel,'Filename':'','FilenameStem':'','Extra':extra,'Now':now,'Env':env}
        try:stem=template.render(no.get('filename','{{id}}'),ctx)
        except Failure as e:raise Failure('new note: '+e.text,e.prefix)
        name=stem+'.'+no.get('extension','md');abspath=os.path.normpath(os.path.join(targetdir,name))
        if not os.path.exists(abspath) or fixed:break
