    ctx['Filename']=os.path.basename(name);ctx['FilenameStem']=os.path.splitext(os.path.basename(name))[0]
    tmplpath=opts.get('template',no.get('template',''));tmpl=''
    if tmplpath:
        expanded=os.path.expanduser(tmplpath)
