        if path in book.conf.get('filter',{}):
            text=book.conf['filter'][path]
            try:sub=CLI(['list']+shlex.split(text))
            except (ValueError,Failure) as e:raise Failure('incorrect criteria: '+str(e))
            for k,v in sub.opts.items():
                if isinstance(v,list):newopts.setdefault(k,[]).extend(v)
                else:newopts[k]=v
            paths+=sub.paths
        else:paths.append(path)
    for k,v in cli.opts.items():
        if isinstance(v,list):newopts.setdefault(k,[]).extend(v)
        else:newopts[k]=v
    cli.opts=newopts;cli.paths=paths

def lsp_server():
    while True:
        header={}
        while True:
            line=sys.stdin.buffer.readline()
            if not line:return
            if line in [b'\r\n',b'\n']:break
            if b':' in line:
                k,v=line.decode().split(':',1);header[k.lower()]=v.strip()
        size=int(header.get('content-length',0));body=sys.stdin.buffer.read(size)
        try:msg=json.loads(body)
        except:continue
        method=msg.get('method')
        if method=='exit':return
        if 'id' not in msg:continue
        result=None
        if method=='initialize':result={'capabilities':{'textDocumentSync':1,'completionProvider':{'triggerCharacters':['[','#',':']},'definitionProvider':True,'referencesProvider':True,'documentLinkProvider':{},'workspaceSymbolProvider':True}}
        elif method in ['textDocument/completion','workspace/symbol','textDocument/references','textDocument/documentLink']:result=[]
        resp=jdump({'jsonrpc':'2.0','id':msg['id'],'result':result}).encode()
        sys.stdout.buffer.write(('Content-Length: '+str(len(resp))+'\r\n\r\n').encode()+resp);sys.stdout.buffer.flush()

def maybe_alias(args):
    # Aliases are deliberately executed as user commands, not as an alternate notebook engine.
    if not args:return False
    command=None;idx=-1;cwd=os.getcwd();nb=None;i=0
    while i<len(args):
        a=args[i]
        if a in ['-W','--working-dir','--notebook-dir'] and i+1<len(args):
            if a=='--notebook-dir':nb=args[i+1]
            else:cwd=os.path.abspath(args[i+1])
            i+=2;continue
        if a.startswith('--notebook-dir='):nb=a.split('=',1)[1]
        elif a.startswith('--working-dir='):cwd=os.path.abspath(a.split('=',1)[1])
        elif not a.startswith('-'):command=a;idx=i;break
        i+=1
    if not command:return False
    root=find_root(nb or os.environ.get('ZK_NOTEBOOK_DIR') or cwd)
    try:
        conf=global_config()
        if root:conf=merge(conf,load_config_file(os.path.join(root,'.zk/config.toml')))
    except Failure:return False
    alias=conf.get('alias',{}).get(command)
    if not alias:return False
    if os.environ.get('_REPLICA_ALIAS')==command:return False
    env=dict(os.environ);env['_REPLICA_ALIAS']=command;env['ZK_NOTEBOOK_DIR']=root or '';env['ZK_SHELL']=os.environ.get('SHELL','')
    own=[os.path.abspath(sys.argv[0])]
    if sys.argv[0].endswith('.py'):own=[sys.executable,os.path.abspath(sys.argv[0])]
    quoted=' '.join(shlex.quote(s) for s in own)
    alias=re.sub(r'(?<![\w/])zk(?=\s|$)',lambda m:quoted,alias)
    shell=os.environ.get('SHELL') or '/bin/sh'
    result=subprocess.run([shell,'-c',alias,'zk']+args[idx+1:],cwd=cwd,env=env)
    raise SystemExit(result.returncode)

def main():
    args=sys.argv[1:]
    if maybe_alias(args):return
    cli=CLI(args);opts=cli.opts;cmd=cli.command
    if opts.get('version'):print('zk dev');return
    if opts.get('help') or not cmd:cli.help();return
    cwd=os.path.abspath(os.path.expanduser(opts.get('working-dir',os.getcwd())))
    if cmd=='graph':
        if 'format' not in opts:raise Failure('missing flags: --format=STRING')
        if opts['format']!='json':raise Failure('--format must be one of "json" but got "'+opts['format']+'"')
    if cmd=='index' and opts.get('verbose') and opts.get('quiet'):raise Failure("--verbose and --quiet can't be used together")
    if cmd=='init':init(cli,cwd);return
    if cmd=='lsp':lsp_server();return
    rootpath=opts.get('notebook-dir') or os.environ.get('ZK_NOTEBOOK_DIR') or cwd
    rootpath=os.path.abspath(os.path.join(cwd,os.path.expanduser(rootpath)))
    if not os.path.exists(rootpath):
        for _ in range(3 if 'working-dir' in opts and 'notebook-dir' not in opts else 2):warn('lstat '+rootpath+': no such file or directory')
    root=find_root(rootpath)
    if not root:raise Failure('failed to open notebook: no notebook found in '+rootpath+' or a parent directory')
    book=Notebook(root)
    if cmd=='new':new(cli,book,cwd);return
    if cmd=='index':
        total,added,modified,removed=book.scan(opts.get('force',False),opts.get('verbose',False))
        if not opts.get('quiet'):print(f'\nIndexed {total} note'+('s' if total>1 else '')+f' in 0s\n  + {added} added\n  ~ {modified} modified\n  - {removed} removed')
