        except FileNotFoundError:raise Failure('exec: "fzf": executable file not found in $PATH')
    if cmd=='list':format_list(notes,cli,book)
    elif cmd=='graph':graph_output(notes,book,opts)
    elif cmd=='edit':
        if not notes:sys.stderr.write('Found 0 notes.\n')
        else:editor(notes,book.conf,cwd)

if __name__=='__main__':
    try:main()
    except Failure as e:
        if e.prefix:sys.stderr.write('zk: error: '+e.text.replace('\n','\n           ')+'\n')
        else:sys.stderr.write(e.text+'\n')
        sys.exit(1)
    except BrokenPipeError:
        try:sys.stdout.close()
        except:pass
        sys.exit(0)
    except KeyboardInterrupt:sys.exit(130)
