#!/usr/bin/env python3
"""An independent plain-text notebook command-line implementation."""
import sys, os, re, subprocess, shlex, random, string, sqlite3, json, zipfile, time
from common import *
from notebook import Notebook, find_root, global_config, load_config_file, warn
from templates import Templates
from query import Selector, sort_items

GLOBAL={'help':'bool','version':'bool','notebook-dir':'str','working-dir':'str','no-input':'bool','debug':'bool'}
FILTER={'interactive':'bool','limit':'int','match':'slice','match-strategy':'str','exclude':'slice','tag':'slice','mention':'slice','mentioned-by':'slice','link-to':'slice','no-link-to':'slice','linked-by':'slice','no-linked-by':'slice','orphan':'bool','tagless':'bool','missing-backlink':'bool','related':'slice','max-distance':'int','recursive':'bool','created':'str','created-before':'str','created-after':'str','modified':'str','modified-before':'str','modified-after':'str','sort':'slice'}
FORMAT={'format':'str','header':'str','footer':'str','delimiter':'str','delimiter0':'bool','no-pager':'bool','quiet':'bool'}
COMMANDS={'init':{},'index':{'force':'bool','verbose':'bool','quiet':'bool'},'new':{'interactive':'bool','title':'str','date':'str','group':'str','extra':'map','template':'str','print-path':'bool','dry-run':'bool','id':'str'},'list':dict(FILTER,**FORMAT),'graph':dict(FILTER,format='str',quiet='bool'),'edit':dict(FILTER,force='bool'),'tag':dict(FORMAT,sort='slice'),'lsp':{}}
SHORT={'h':'help','W':'working-dir'}
SHORT_BY={'index':{'f':'force','v':'verbose','q':'quiet'},'new':{'i':'interactive','t':'title','g':'group','p':'print-path','n':'dry-run'},'list':{'f':'format','d':'delimiter','0':'delimiter0','P':'no-pager','q':'quiet'},'graph':{'f':'format','q':'quiet'},'edit':{'f':'force'},'tag':{'f':'format','d':'delimiter','0':'delimiter0','P':'no-pager','q':'quiet','s':'sort'}}
SHORT_FILTER={'i':'interactive','n':'limit','m':'match','M':'match-strategy','x':'exclude','t':'tag','l':'link-to','L':'linked-by','r':'recursive','s':'sort'}

def resource(name):
    if zipfile.is_zipfile(sys.argv[0]):
        with zipfile.ZipFile(sys.argv[0]) as z:return z.read(name).decode()
    return open(os.path.join(os.path.dirname(os.path.dirname(__file__)),name),encoding='utf-8').read()

def csv_values(s):
    return [p.replace('\\,',',') for p in re.split(r'(?<!\\),',s)]

class CLI:
    def __init__(self,args):
        self.opts={};self.seen=set();self.paths=[];self.command=None;self.tag_sub=False;self.args=args
        self.parse(args)
    def parse(self,args):
        i=0;end=False
        while i<len(args):
            arg=args[i];i+=1
            if arg=='--':end=True;continue
            if not end and arg.startswith('-') and arg!='-':
                defs=dict(GLOBAL);defs.update(COMMANDS.get(self.command,{}));short=dict(SHORT)
                if self.command in ['list','graph','edit']:short.update(SHORT_FILTER)
                short.update(SHORT_BY.get(self.command,{}))
                queued=[]
                if arg.startswith('--'):
                    key,sep,value=arg[2:].partition('=');queued=[(key,value if sep else None,'--'+key)]
                else:
                    group=arg[1:];j=0
                    while j<len(group):
                        ch=group[j];key=short.get(ch)
                        if not key:raise Failure('unknown flag -'+ch)
                        j+=1
                        val=None
                        if defs.get(key)!='bool' and j<len(group):val=group[j:];j=len(group)
                        queued.append((key,val,'-'+ch))
                        if defs.get(key)!='bool':break
                for key,val,orig in queued:
                    if key not in defs:raise Failure('unknown flag '+orig)
                    ty=defs[key];self.seen.add(key)
                    if ty=='bool':
                        if val is None:self.opts[key]=True
                        elif val.lower() in ['true','1','false','0']:self.opts[key]=val.lower() in ['true','1']
                        else:raise Failure('--'+key+': expected a valid bool but got "'+val+'"')
                        continue
                    if val is None:
                        if i>=len(args):raise Failure('--'+key+': expected one argument')
                        val=args[i];i+=1
                    if val.startswith('-') and val!='-':
                        vtype='int' if ty=='int' else 'string'
                        cls='long flag' if val.startswith('--') else 'short flag'
                        raise Failure(f'--{key}: expected {vtype} value but got "{val}" ({cls}); perhaps try --{key}="{val}"?')
                    if ty=='int':
                        try:value=int(val)
                        except:raise Failure('--'+key+': expected a valid 64 bit int but got "'+val+'"')
                        self.opts[key]=value
                    elif ty=='slice':self.opts.setdefault(key,[]).extend(csv_values(val))
                    elif ty=='map':
                        for p in csv_values(val):
                            k,sep,v=p.partition('=')
                            if not sep:raise Failure('--'+key+': expected "<key>=<value>" but got "'+p+'"')
                            self.opts.setdefault(key,{})[k]=v
                    else:self.opts[key]=val
                continue
            if self.command is None:
                if arg not in COMMANDS:raise Failure('unexpected argument '+arg)
                self.command=arg;continue
            if self.command=='tag' and not self.tag_sub:
                if arg!='list':raise Failure('unexpected argument '+arg)
                self.tag_sub=True;continue
            if self.command in ['index','tag','lsp'] or (self.command in ['init','new'] and self.paths):raise Failure('unexpected argument '+arg)
            self.paths.append(arg)
    def help(self):
        name=self.command or 'root'
        if name=='tag' and self.tag_sub:name='tag_list'
        sys.stdout.write(resource('helps/'+name+'.txt'))


def report_count(n,kind='note',graph=False):
    sys.stderr.write(('\n\n' if graph else '\n')+f'Found {n} {kind}'+('s' if n>1 else '')+'\n')

def pretty_note(n,fmt,language):
    title=n['title'];path=n['path'];snippets=n.get('snippets',[])
    if fmt in ['oneline','short']:
        head=f'{title} {path} ({relative(n["created"])})'
    else:
        head=f'{title} {path}\nCreated: '+date_fmt(n['created'],'short',language)
        if fmt in ['long','full']:head+='\nModified: '+date_fmt(n['modified'],'short',language)
    if fmt=='oneline':return head
    if fmt=='full':
        head+='\nTags: '+', '.join(n['tags'])+'\n\n'
        body=n['body']
        return head+('  '+body.replace('\n','\n  ') if body else '')+'\n'
    return head+'\n\n'+''.join('  - '+s.replace('\n','\n    ')+'\n' for s in snippets)

def format_list(notes,cli,book,is_tag=False):
    opts=cli.opts;fmt=opts.get('format','full' if is_tag else 'short')
    if opts.get('delimiter0') and 'delimiter' in cli.seen:raise Failure("--delimiter and --delimiter0 can't be used together")
    if fmt in ['json','jsonl']:
        for key in ['header','footer','delimiter']:
            if key in cli.seen or (key=='footer' and opts.get('delimiter0')):raise Failure('--'+key+" can't be used with JSON format")
    if not notes:
        if not opts.get('quiet'):report_count(0,'tag' if is_tag else 'note')
        return
    language=book.conf['note'].get('language','en')
    if fmt=='json':text='['+','.join(jdump(n) for n in notes)+']\n'
    elif fmt=='jsonl':text=''.join(jdump(n)+'\n' for n in notes)
    else:
        delimiter=unescape(opts.get('delimiter','\n'))
        footer=unescape(opts.get('footer','\n'))
        if opts.get('delimiter0'):delimiter=footer='\0'
        rendered=[]
        for n in notes:
            if is_tag and fmt in ['name','full']:
                r=n['name']+(f' ({n["noteCount"]})' if fmt=='full' else '')
            elif not is_tag and fmt in ['oneline','short','medium','long','full']:r=pretty_note(n,fmt,language)
            else:
                template='{{'+fmt+'}}' if fmt in ['path','link'] and not is_tag else fmt
                r=Templates(language).render(template,n)
            rendered.append(r)
        text=unescape(opts.get('header',''))+delimiter.join(rendered)+footer
    sys.stdout.write(text)
    if not opts.get('quiet'):report_count(len(notes),'tag' if is_tag else 'note')

def graph_output(notes,book,opts):
    ids={n['_id'] for n in notes};links=[l for l in book.links if l['sourceId'] in ids and l['targetId'] in ids]
