def editor(notes,conf,cwd):
    ed=conf.get('tool',{}).get('editor') or os.environ.get('EDITOR') or os.environ.get('VISUAL')
    if not ed:raise Failure('no editor set in config')
    words=shlex.split(os.path.expandvars(ed))
    if not words:raise Failure('no editor set in config')
    args=words+[n['absPath'] if isinstance(n,dict) else n for n in notes]
    try:
        result=subprocess.run(args,cwd=cwd)
    except FileNotFoundError:raise Failure('exec: "'+args[0]+'": executable file not found in $PATH')
