        except:raise Failure('EOF')
    print()
    root=find_root(path)
    if root:raise Failure('init: a notebook already exists in '+root)
    try:
        os.makedirs(os.path.join(path,'.zk','templates'),exist_ok=True)
        open(os.path.join(path,'.zk/config.toml'),'w').write(resource('resources/default-config.toml'))
        open(os.path.join(path,'.zk/templates/default.md'),'w').write(resource('resources/default.md'))
    except OSError as e:raise Failure('init: '+str(e))
    book=Notebook(path);book.open_state();book.save()
    print('Initialized a notebook in '+path)

def new(cli,book,cwd):
    opts=cli.opts;patharg=cli.paths[0] if cli.paths else cwd
    targetdir=os.path.abspath(os.path.join(cwd,os.path.expanduser(patharg)))
    if not os.path.isdir(targetdir):raise Failure('new note: '+patharg+': directory not found')
    rel=os.path.relpath(targetdir,book.root)
    if rel=='..' or rel.startswith('../'):raise Failure('new note: '+targetdir+': path is outside the notebook at '+book.root)
