    if not args:raise RPCError(cmd+' expects a notebook path as first argument')
    if not isinstance(args[0],str):raise RPCError(cmd+' expects a notebook path as first argument, got: '+gofmt(args[0]))
    root=find_root(args[0])
    if not root:raise RPCError('failed to open notebook: no notebook found in '+args[0]+' or a parent directory')
    opts=args[1] if len(args)>1 and isinstance(args[1],dict) else {}
